// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type SkyscraperCollapseProps = Record<string, any>;

const SkyscraperCollapse: React.FC<SkyscraperCollapseProps> = ({
  backgroundColor = "#073e87",
  transparentBackground = false,
  durationInSeconds = 6,
  skyColor = "#073e87",
  buildingColor = "#d6dee6",
  glassColor = "#1a3c5a",
  dirtColor = "#71513a",
  crackColor = "#1c1410",
  impactForce = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBgColor = transparentBackground ? `${backgroundColor}00` : skyColor;

  // ANIMATION TIMINGS & PHASES (scaled dynamically to composition duration)
  const totalFrames = durationInSeconds * fps;
  const startTremor = Math.floor(0.15 * totalFrames);
  const startCollapse = Math.floor(0.3 * totalFrames);
  const startDustRelease = Math.floor(0.35 * totalFrames);

  // Tremor phase before the falling start (poor foundations shaking)
  const tremorProgress = interpolate(frame, [startTremor, startCollapse], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const shakeX = tremorProgress > 0 && frame < startCollapse
    ? Math.sin(frame * 1.5) * 5 * tremorProgress * impactForce
    : 0;

  // Main collapse animation driven by spring physics for realistic acceleration
  const fallSpring = spring({
    frame: Math.max(0, frame - startCollapse),
    fps,
    config: {
      mass: 5 / impactForce,
      damping: 18,
      stiffness: 30,
    },
  });

  // Interpolated values for rotation and displacement of the falling tower
  const towerRotate = interpolate(fallSpring, [0, 1], [0, -32], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const towerTranslateX = interpolate(fallSpring, [0, 1], [0, -width * 0.1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const towerTranslateY = interpolate(fallSpring, [0, 1], [0, height * 0.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Foundation crumble progress
  const foundationBreak = interpolate(frame, [startCollapse, startCollapse + 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Debris & dust cloud particles dynamic motion
  const dustOpacity = interpolate(
    frame,
    [startDustRelease, startDustRelease + 15, totalFrames - 15, totalFrames],
    [0, 0.9, 0.7, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const dustScale = interpolate(frame, [startDustRelease, totalFrames], [0.8, 2.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Procedural debris positioning and physical trajectory
  const generateDebris = (count: number) => {
    return Array.from({ length: count }).map((_, i) => {
      const angle = (i / count) * Math.PI * 1.2 - Math.PI * 0.2;
      const initialDelay = startCollapse + (i % 5) * 4;
      
      const flightProgress = spring({
        frame: Math.max(0, frame - initialDelay),
        fps,
        config: { mass: 1, damping: 12, stiffness: 45 },
      });

      const maxDistanceX = (Math.cos(angle) * width * 0.4 - width * 0.1) * impactForce;
      const maxDistanceY = (Math.sin(angle) * height * 0.3 + height * 0.4) * impactForce;

      const x = interpolate(flightProgress, [0, 1], [0, maxDistanceX]);
      const y = interpolate(flightProgress, [0, 1], [0, maxDistanceY]);
      const rotate = interpolate(flightProgress, [0, 1], [0, i * 180]);
      const size = 12 + (i % 4) * 6;
      const opacity = interpolate(flightProgress, [0.8, 1], [1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });

      return { x, y, rotate, size, opacity, key: i };
    });
  };

  const debrisPieces = generateDebris(16);

  // Text Animation
  const textY = interpolate(frame, [0, 30], [50, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textOpacity = interpolate(frame, [0, 25, totalFrames - 15, totalFrames], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* HUD / Caption Text */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          width: "100%",
          textAlign: "center",
          color: "#ffffff",
          zIndex: 10,
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          transition: "none",
        }}
      >
        <h1 style={{ fontSize: "2.8rem", margin: "0 0 8px 0", fontWeight: 800, textTransform: "uppercase", letterSpacing: "2px", textShadow: "0 4px 12px rgba(0,0,0,0.5)" }}>
          STRUCTURAL BREAKDOWN
        </h1>
        <p style={{ fontSize: "1.2rem", margin: 0, opacity: 0.8, fontWeight: 500, letterSpacing: "1px" }}>
          FOUNDATION QUALITY: CRITICAL FAIL
        </p>
      </div>

      {/* Main Sandbox Stage container */}
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-end",
          paddingBottom: height * 0.12,
        }}
      >
        {/* CRITICAL FOUNDATION / GROUND */}
        <div
          style={{
            position: "absolute",
            width: width * 0.85,
            height: height * 0.18,
            bottom: height * 0.08,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            zIndex: 4,
          }}
        >
          {/* Top crust edge of foundation */}
          <div
            style={{
              width: "100%",
              height: 24,
              backgroundColor: "#9e9e9e",
              borderBottom: "6px solid #616161",
              borderRadius: "4px 4px 0 0",
              boxShadow: "0 8px 16px rgba(0,0,0,0.4)",
              position: "relative",
              overflow: "hidden",
            }}
          >
            {/* Crack lines on foundation */}
            <svg style={{ position: "absolute", width: "100%", height: "100%", left: 0, top: 0 }}>
              <path
                d="M 120 0 L 125 10 L 118 24 M 280 0 L 290 8 L 285 24 M 500 0 L 495 12 L 505 24"
                stroke={crackColor}
                strokeWidth="4"
                fill="none"
                style={{
                  opacity: foundationBreak,
                  transition: "none",
                }}
              />
            </svg>
          </div>

          {/* Earth/Dirt Core with Failing Foundation Columns */}
          <div
            style={{
              width: "95%",
              flex: 1,
              backgroundColor: dirtColor,
              borderRadius: "0 0 24px 24px",
              position: "relative",
              overflow: "hidden",
              border: `5px solid ${crackColor}`,
              borderTop: "none",
              display: "flex",
              justifyContent: "space-around",
              padding: "10px 20px 0 20px",
            }}
          >
            {/* Structural Piles / Failing Foundation Pillars */}
            {[0, 1, 2, 3].map((i) => {
              const rot = i === 0 || i === 1
                ? interpolate(foundationBreak, [0, 1], [0, -18 + i * 4])
                : interpolate(foundationBreak, [0, 1], [0, 12 - (i - 2) * 4]);
              const dY = interpolate(foundationBreak, [0, 1], [0, 25]);
              return (
                <div
                  key={i}
                  style={{
                    width: "16%",
                    height: "85%",
                    backgroundColor: "#8a8a8a",
                    border: `4px solid ${crackColor}`,
                    borderBottom: "none",
                    borderRadius: "4px",
                    transform: `rotate(${rot}deg) translateY(${dY}px)`,
                    transformOrigin: "bottom center",
                    boxShadow: "inset -8px 0px 0px rgba(0,0,0,0.2)",
                    position: "relative",
                    transition: "none",
                  }}
                >
                  {/* Pillar cracks */}
                  <svg style={{ position: "absolute", width: "100%", height: "100%" }}>
                    <path
                      d="M 0 20 L 15 30 L 5 45 M 20 5 L 10 25 L 18 50"
                      stroke={crackColor}
                      strokeWidth="2.5"
                      fill="none"
                    />
                  </svg>
                </div>
              );
            })}
          </div>
        </div>

        {/* SKYSCRAPER TOWER CONTAINER */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.22,
            width: width * 0.46,
            height: height * 0.55,
            transformOrigin: "bottom right",
            transform: `translateX(${towerTranslateX + shakeX}px) translateY(${towerTranslateY}px) rotate(${towerRotate}deg)`,
            zIndex: 3,
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end",
            transition: "none",
          }}
        >
          {/* Spire */}
          <div
            style={{
              width: 8,
              height: height * 0.06,
              backgroundColor: buildingColor,
              margin: "0 auto",
              position: "relative",
              borderRadius: "4px 4px 0 0",
            }}
          >
            {/* Warning beacon */}
            <div
              style={{
                position: "absolute",
                top: -6,
                left: -2,
                width: 12,
                height: 12,
                backgroundColor: frame % 15 < 7 ? "#ff3333" : "#550000",
                borderRadius: "50%",
                boxShadow: "0 0 12px #ff3333",
              }}
            />
          </div>

          {/* Top Tier (Penthouse) */}
          <div
            style={{
              width: "60%",
              height: "12%",
              backgroundColor: buildingColor,
              margin: "0 auto",
              border: `4px solid ${crackColor}`,
              borderBottom: "none",
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gap: "4px",
              padding: "6px 8px 0 8px",
              boxSizing: "border-box",
            }}
          >
            {[...Array(3)].map((_, idx) => (
              <div key={idx} style={{ backgroundColor: glassColor, borderRadius: "2px" }} />
            ))}
          </div>

          {/* Middle Tier */}
          <div
            style={{
              width: "82%",
              height: "25%",
              backgroundColor: buildingColor,
              margin: "0 auto",
              border: `5px solid ${crackColor}`,
              borderBottom: "none",
              display: "grid",
              gridTemplateColumns: "repeat(4, 1fr)",
              gridTemplateRows: "repeat(2, 1fr)",
              gap: "6px 4px",
              padding: "8px",
              boxSizing: "border-box",
              position: "relative",
            }}
          >
            {[...Array(8)].map((_, idx) => (
              <div key={idx} style={{ backgroundColor: glassColor, borderRadius: "2px" }} />
            ))}
          </div>

          {/* Main Base Tower Tier */}
          <div
            style={{
              width: "100%",
              height: "63%",
              backgroundColor: buildingColor,
              border: `6px solid ${crackColor}`,
              boxSizing: "border-box",
              display: "flex",
              flexDirection: "column",
              justifyContent: "space-between",
              padding: "12px 10px",
              boxShadow: "inset -24px 0px 0px rgba(0,0,0,0.1)",
              position: "relative",
            }}
          >
            {/* Windows Matrix grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(5, 1fr)",
                gridTemplateRows: "repeat(5, 1fr)",
                gap: "8px 6px",
                flex: 1,
              }}
            >
              {[...Array(25)].map((_, idx) => {
                // Some windows flicker/break as structural damage propagates
                const isBroken = idx % 7 === 0 && frame > startCollapse + 10;
                return (
                  <div
                    key={idx}
                    style={{
                      backgroundColor: isBroken ? "#111111" : glassColor,
                      borderRadius: "3px",
                      border: isBroken ? "1px solid #ff5555" : "none",
                      boxShadow: isBroken ? "none" : "inset 2px 2px 0px rgba(255,255,255,0.15)",
                      position: "relative",
                      transition: "none",
                    }}
                  >
                    {isBroken && (
                      <div
                        style={{
                          position: "absolute",
                          width: "100%",
                          height: "100%",
                          backgroundColor: "rgba(255, 100, 100, 0.3)",
                        }}
                      />
                    )}
                  </div>
                );
              })}
            </div>

            {/* Dynamic Crack System growing across face of building */}
            <svg
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                pointerEvents: "none",
              }}
            >
              <path
                d="M 120 320 L 100 240 L 140 160 L 90 90 L 110 20"
                stroke={crackColor}
                strokeWidth="5"
                fill="none"
                strokeDasharray="400"
                strokeDashoffset={interpolate(frame, [startTremor, startCollapse + 15], [400, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                })}
                style={{ transition: "none" }}
              />
              <path
                d="M 100 240 L 40 180 L 60 110"
                stroke={crackColor}
                strokeWidth="3.5"
                fill="none"
                strokeDasharray="200"
                strokeDashoffset={interpolate(frame, [startCollapse, startCollapse + 20], [200, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                })}
                style={{ transition: "none" }}
              />
            </svg>

            {/* Crumbling Base Stress Lines */}
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                width: "100%",
                height: "20px",
                backgroundColor: "#7c7c7c",
                borderTop: `4px solid ${crackColor}`,
              }}
            />
          </div>
        </div>

        {/* COLLAPSE PHYSICS PARTICLES (Debris & Dust Elements) */}
        {frame >= startCollapse && (
          <div
            style={{
              position: "absolute",
              bottom: height * 0.22,
              width: width * 0.5,
              height: height * 0.4,
              right: width * 0.15,
              zIndex: 5,
              pointerEvents: "none",
            }}
          >
            {debrisPieces.map((p) => (
              <div
                key={p.key}
                style={{
                  position: "absolute",
                  bottom: "10%",
                  right: "20%",
                  width: p.size,
                  height: p.size,
                  backgroundColor: "#a0a0a0",
                  border: `2px solid ${crackColor}`,
                  boxShadow: "3px 3px 0px rgba(0,0,0,0.3)",
                  transform: `translate(${p.x}px, ${-p.y}px) rotate(${p.rotate}deg)`,
                  opacity: p.opacity,
                  borderRadius: p.key % 3 === 0 ? "50%" : "2px",
                  transition: "none",
                }}
              />
            ))}
          </div>
        )}

        {/* Dust Clouds / Smoke plumes rising from the base impact */}
        <div
          style={{
            position: "absolute",
            width: width * 0.9,
            height: height * 0.2,
            bottom: height * 0.18,
            zIndex: 6,
            pointerEvents: "none",
            display: "flex",
            justifyContent: "space-around",
            alignItems: "flex-end",
            opacity: dustOpacity,
            transform: `scale(${dustScale})`,
            transformOrigin: "bottom center",
            transition: "none",
          }}
        >
          {[...Array(5)].map((_, i) => (
            <div
              key={i}
              style={{
                width: 90 + (i % 3) * 30,
                height: 80 + (i % 2) * 25,
                backgroundColor: "rgba(210, 195, 180, 0.75)",
                borderRadius: "50%",
                filter: "blur(12px)",
                margin: "-20px",
                boxShadow: "0 -10px 30px rgba(139,115,85,0.4)",
              }}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SkyscraperCollapse;